//! Recorded TPM exchanges, for the unit tests of `marshal`, `provision` and `endorsement`.
//!
//! Recorded on 2026-10-29 from swtpm 0.7.1 with libtpms 0.9.2 (the Debian trixie packages of
//! `crates/testkit/src/swtpm/Containerfile`), one fresh TPM, in this order: tpm2-tools 5.7 made
//! the standard storage root key (`tpm2_createprimary -C o -g sha256 -G ecc256:aes128cfb`) and
//! persisted it at 0x81000001; then the commands below, as `marshal` builds them, went over
//! swtpm's command port. The keys belong to that throwaway software TPM and exist nowhere else;
//! `CREATE_RESPONSE`'s private part is encrypted under its storage key.
//!
//! Commands are written with `_` between their fields: header, handles, authorization area,
//! parameters.

/// TPM2_ReadPublic of 0x81000001: the SRK made by tpm2-tools.
pub(crate) const READ_PUBLIC_SRK_RESPONSE: &str = "";

/// TPM2_CreatePrimary with the SRK template.
pub(crate) const CREATE_PRIMARY_COMMAND: &str = "8002_00000043_00000131_40000001_00000009_40000009_0000_00_0000_0004_0000_0000_001a_0023_000b_00030072_0000_0006_0080_0043_0010_0003_0010_0000_0000_0000_00000000";
/// Its response: the same key as the SRK (same seed, same template), loaded at 0x80000000.
pub(crate) const CREATE_PRIMARY_RESPONSE: &str = "";

/// TPM2_FlushContext of that primary, and its response.
pub(crate) const FLUSH_PRIMARY_COMMAND: &str = "8001_0000000e_00000165_80000000";
pub(crate) const FLUSH_CONTEXT_RESPONSE: &str = "80010000000a00000000";

/// TPM2_Create of the gateway key's template under 0x81000001.
pub(crate) const CREATE_COMMAND: &str = "8002_00000041_00000153_81000001_00000009_40000009_0000_00_0000_0004_0000_0000_0018_0023_000b_00040072_0000_0010_0018_000b_0003_0010_0000_0000_0000_00000000";
/// The first answer to that command: TPM_RC_RETRY (the TPM did not run it; send it again).
pub(crate) const RETRY_RESPONSE: &str = "80010000000a00000922";
/// The answer to the second try.
pub(crate) const CREATE_RESPONSE: &str = "";

/// TPM2_Load of what TPM2_Create returned, under 0x81000001.
pub(crate) const LOAD_COMMAND: &str = "8002_000000f5_00000157_81000001_00000009_40000009_0000_00_0000_007e002011ba29200d14407bb994cafaeb7982e8cde4248e4c3eacccf6abe00049c14565001096db02aeb55009f0f2ae62b9ee3612e4a66c74ccb24ae22cf01e1ebed37e1adff86db4357e8d501aa0601cbb7facb119f4967df86a08f97f3ed49bb2b5aae64e0bb4b87cc7efac18b57e2b58629cc37a2816cd8d0e9ab9e771f8_00580023000b00040072000000100018000b0003001000209c4d7d297819f2b526943ac51f1e0c39690228008fbbeeb73e35423306bd758a0020ad77a88d5ffd3bf01f824ee36d64f2b500803508ec41b2c19e172556b304d2c7";
