/// TPM2_EvictControl of 0x80000001 to 0x81000100.
pub(crate) const EVICT_CONTROL_COMMAND: &str =
    "8002_00000023_00000120_40000001_80000001_00000009_40000009_0000_00_0000_81000100";
pub(crate) const EVICT_CONTROL_RESPONSE: &str = "80020000001300000000000000000000010000";
/// The same command once more: TPM_RC_NV_DEFINED, 0x81000100 is taken.
pub(crate) const EVICT_CONTROL_DEFINED_RESPONSE: &str = "80010000000a0000014c";

/// TPM2_FlushContext of the loaded key (its response is [`FLUSH_CONTEXT_RESPONSE`]).
pub(crate) const FLUSH_KEY_COMMAND: &str = "8001_0000000e_00000165_80000001";
/// The same flush once more: TPM_RC_HANDLE, nothing is loaded there any more.
pub(crate) const FLUSH_UNKNOWN_RESPONSE: &str = "80010000000a000001cb";

/// TPM2_ReadPublic of 0x81000100 after the eviction: the key TPM2_Create made.
