pub(crate) const EK_CREATE_PRIMARY_RESPONSE: &str = "";
/// The same command with an authorization set on the endorsement hierarchy: TPM_RC_BAD_AUTH
/// for session 1.
pub(crate) const EK_CREATE_PRIMARY_BAD_AUTH_RESPONSE: &str = "80010000000a000009a2";
